files.oldContent:
/* Baseline Styles (Production) */
.hero-container {
  padding: 24px;
  background: #ffffff;
  color: #1e293b;
  border-radius: 8px;
}

.cta-button {
  background-color: #2563eb;
  color: #ffffff;
  font-size: 14px;
  padding: 10px 20px;
  border-radius: 6px;
}

files.newContent:
/* Live Visual Hotfix via Axon Inspector */
.hero-container {
  padding: 32px;
  background: linear-gradient(135deg, #0f172a, #1e1b4b);
  color: #f8fafc;
  border-radius: 12px;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.3);
}

.cta-button {
  background: linear-gradient(135deg, #4f46e5, #6366f1);
  color: #ffffff;
  font-size: 15px;
  font-weight: 700;
  padding: 12px 24px;
  border-radius: 10px;
  box-shadow: 0 4px 14px rgba(79, 70, 229, 0.4);
}

